Íme egy minimálisan működő, de jól bővíthető RAG (RetrievalAugmented Generation) chatbot megoldás Replithez, ahol:

 Backend: Python (FastAPI), egy /chat endpoint, amely becsatolja az Exa APIt és a Cerebras Llama 4 Scout modellt.
 Frontend: Teljes reszponzív, magyar nyelvű chat UI (index.html), ami fetchcsel hívja a backendet.

A példában az összes titkos kulcsot (EXA/LLAMA) env változóból (pl. .env vagy Replit Secrets) olvassa, a Google Service Account csak backend belső erőforrásokhoz kell, nem az LLM/keresőhöz.  
A következő kódot Repliten azonnal tudod futtatni.

 main.py (FastAPI backend teljes kód)

python
import os
import requests
from fastapi import FastAPI, Request
from fastapi.middleware.cors import CORSMiddleware
from pydantic import BaseModel

# ENV-ből vedd át a kulcsokat (Replit-en a Secrets panelen állítsd be: EXA_API_KEY, CEREBRAS_API_KEY)
EXA_API_KEY = os.getenv("EXA_API_KEY")
CEREBRAS_API_KEY = os.getenv("CEREBRAS_API_KEY")

app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],  # fejlesztéshez engedélyezett, prod-ban szűkítsd
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class ChatRequest(BaseModel):
    message: str

@app.post("/chat")
async def chat_endpoint(req: ChatRequest):
    user_message = req.message

    # 1. Exa API: keresés a neten
    exa_resp = requests.get(
        "https://api.exa.ai/search",
        params={"q": user_message, "num_results": 10},
        headers={"Authorization": f"Bearer {EXA_API_KEY}"}
    )
    data = exa_resp.json()
    sources = data.get("results", data.get("documents", [])) # exa régi/új format is támogatott

    # Szövegkivágás + forráslink
    context_chunks = []
    refs = []
    for s in sources:
        text = s.get("snippet") or s.get("text") or ""
        url = s.get("url") or s.get("link") or ""
        if text:
            context_chunks.append(f"{text}\nForrás: {url}" if url else text)
        if url:
            refs.append(url)
    if not context_chunks:
        context_chunks.append("(Nem találtam releváns forrást, csak az alaptudásból válaszolok.)")

    context_string = "\n\n".join(context_chunks[:5])

    # 2. Llama4 Scout hívás a Cerebras AI-on
    payload = {
        "model": "llama-4-scout-17b-16e-instruct",
        "messages": [
            {"role": "system", "content": "A felhasználó kérdésére webes találatokat felhasználva, magyarul, tömören válaszolj, ha van elérhető forrás."},
            {"role": "user", "content": f"{user_message}\n\nWebes források:\n{context_string}"}
        ],
        "temperature": 0.7,
        "max_tokens": 512
    }
    cb_resp = requests.post(
        "https://api.cerebras.ai/v1/chat/completions",
        headers={"Authorization": f"Bearer {CEREBRAS_API_KEY}", "Content-Type": "application/json"},
        json=payload,
        timeout=60
    )
    cb_json = cb_resp.json()
    # Llama válasz kinyerése
    try:
        answer = cb_json['choices'][0]['message']['content'].strip()
    except Exception:
        answer = "Hiba történt a modell válaszának feldolgozásakor."

    return {
        "answer": answer,
        "sources": refs[:5]
    }


