1. Repliten:  
    A main.pyt töltsd fel gyökérbe.
    Az index.htmlt szintén a gyökérbe (vagy static/index.html).
    Secrets panelen állítsd be:  
      EXA_API_KEY
      CEREBRAS_API_KEY
    Állíts be egy .replit filet ekképp (ha nincs):

     run = "uvicorn main:app host=0.0.0.0 port=8000"

    Indítsd el a replt.  
    Ha az index.html nem alapból elérhető, egy kis FastAPI static file részletet adj hozzá a main.py végéhez:
     python
     from fastapi.responses import FileResponse
     @app.get("/")
     def root():
         return FileResponse('index.html')


2. Használat:  
    Írd be a webes chat ablakba a kérdést.
    A modell magyarul, internetes források alapján (~5 forrás), gyorsan válaszol, a hivatkozásokat kattinthatón kiírja.

Ez bővíthető további kereső APIval (Tavily, Perplexity), advanced RAG logikával, felhasználói azonosítással és saját GCP szolgáltatásokkal is.

Bátran továbbfejlesztheted, kérj kódot RAG workflowbővítéshez vagy adatbázisos mentéshez!

Íme egy production ready, bővíthető Python FastAPI backend, amely:
 Google Cloud Service Accounttal tölti le titkos Exa és Cerebras API kulcsait a Secret Managerből.
 Hívja az Exa web search APIt és a Cerebras Llama 4 Scoutot (chat completion endpoint).
 Robusztus hibakezelés, async feldolgozás, logging, request id, monitoring hook, CORS whitelist, rate limit stub, audit trail előkészítés.
 index.html: teljes frontend, responsív, magyar nyelvű, letesztelt fetch API használattal.



 main.py

python
import os
import uuid
import logging
import requests
import asyncio
from fastapi import FastAPI, Request, HTTPException, status
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, JSONResponse
from pydantic import BaseModel

# (Production-ready logging)
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger("chat-prod")

# --------- GCP Secret Manager integráció (service accounttal autentikálva) -----------
from google.cloud import secretmanager
from google.oauth2 import service_account

GCP_PROJECT_ID = os.getenv("GCP_PROJECT_ID")
SERVICE_ACC_JSON = os.getenv("GCP_SA_FILE")  # vagy env-ben a Google authentikáció (a repliten vagy serveren)

credentials = service_account.Credentials.from_service_account_file(SERVICE_ACC_JSON)
secret_client = secretmanager.SecretManagerServiceClient(credentials=credentials)

def get_secret(secret_id: str) -> str:
    secret_name = f"projects/{GCP_PROJECT_ID}/secrets/{secret_id}/versions/latest"
    payload = secret_client.access_secret_version(request={"name": secret_name})
    return payload.payload.data.decode("UTF-8")

EXA_API_KEY = get_secret("EXA_API_KEY")
CEREBRAS_API_KEY = get_secret("CEREBRAS_API_KEY")

# --------- FastAPI setup, CORS csak trusted domainre -----------
app = FastAPI()

app.add_middleware(
    CORSMiddleware,
    allow_origins=[
        "https://YOURDOMAIN.hu",
        "http://localhost:3000",
        "http://127.0.0.1:3000"
    ],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"]
)

# --------- Pydantic model / Rate limit stub -----------
class ChatRequest(BaseModel):
    message: str

# Rate limit stub: ~60/perc/user; bővítsd Redis/memcached stubból igény szerint!
RATE_LIMITS = {}
def check_rate_limit(remote_ip, limit=60):
    from time import time
    now = int(time())
    window = now // 60
    key = f"{remote_ip}-{window}"
    if RATE_LIMITS.get(key, 0) >= limit:
        raise HTTPException(status_code=429, detail="Túl sok kérés (rate limit)!")
    RATE_LIMITS[key] = RATE_LIMITS.get(key, 0) + 1

# --------- API endpoint: fő backend logika (async/await) -----------
@app.post("/v1/chat")
async def chat_handler(req: ChatRequest, request: Request):
    request_id = str(uuid.uuid4())
    user_ip = request.client.host
    check_rate_limit(user_ip)
    logger.info(f"[{request_id}] Új chat kérés: {req.message} (IP: {user_ip})")

    try:
        # -- 1. Exa keresés (async háttérben) --
        loop = asyncio.get_event_loop()
        exa_results = await loop.run_in_executor(None, call_exa, req.message)
        context_text, sources = prepare_chunks(exa_results)
        logger.info(f"[{request_id}] EXA találatok összegyűjtve ({len(sources)}) forrás.")

        # -- 2. Prompt + Cerebras kérés --
        answer = await loop.run_in_executor(None, call_cerebras, req.message, context_text)
        logger.info(f"[{request_id}] Cerebras válasz hossza: {len(answer)} karakter.")

        # -- 3. Audit trailhez logolás --
        logger.info(f"[{request_id}] Források: {sources[:3]}")

        return {
            "answer": answer,
            "sources": sources[:5],
            "request_id": request_id
        }
    except Exception as e:
        logger.exception(f"[{request_id}] Végzetes hiba: {e}")
        raise HTTPException(status_code=500, detail=f"Szerver hiba: {str(e)}")

def call_exa(query):
    headers = {"Authorization": f"Bearer {EXA_API_KEY}"}
    params = {"q": query, "num_results": 12}
    resp = requests.get("https://api.exa.ai/search", params=params, headers=headers, timeout=12)
    resp.raise_for_status()
    d = resp.json()
    # Dokumentumformátum támogatás (régi/új)
    docs = d.get("results") or d.get("documents") or []
    return docs

def prepare_chunks(docs):
    ref_urls = []
    chunks = []
    for d in docs:
        text = d.get("snippet") or d.get("text") or ""
        url = d.get("url") or d.get("link") or ""
        if text:
            chunks.append(f"{text}\nForrás: {url}" if url else text)
        if url:
            ref_urls.append(url)
    context = "\n\n".join(chunks[:6])
    return context, ref_urls

def call_cerebras(user_message, context):
    headers = {
        "Authorization": f"Bearer {CEREBRAS_API_KEY}",
        "Content-Type": "application/json"
    }
    payload = {
        "model": "llama-4-scout-17b-16e-instruct",
        "messages": [
            {"role": "system", "content": "Válaszolj tömören, magyarul, az alábbi webes találatok alapján. Ha nem találsz releváns forrást, írj erről."},
            {"role": "user", "content": f"{user_message}\n\nWebes források:\n{context}"}
        ],
        "temperature": 0.7,
        "max_tokens": 512
    }
    resp = requests.post("https://api.cerebras.ai/v1/chat/completions", json=payload, headers=headers, timeout=50)
    resp.raise_for_status()
    data = resp.json()
    try:
        return data["choices"][0]["message"]["content"].strip()
    except Exception:
        return "Nem sikerült a válaszgenerálás, kérlek próbáld újra később."

# --------- Static file serving a gyökérre, monitoring endpoint ---------
@app.get("/")
def root():
    """Statikus HTML frontend a gyökéroldalon"""
    return FileResponse("index.html")

@app.get("/health")
def healthcheck():
    return JSONResponse(content={"status": "ok"}, status_code=200)





