 Kulcs production szempontok:

 Kulcsok: NEM kódban/lemezben, csak GCP Secret Managerből service accal! (lásd main.py)
 CORS: csak trusted hostokra nyitott.
 Rate limiting: IP/user szinten (bővítsd Redis clusterrel!)
 Logging/audit trail: request id, hibák, forráslog.
 Hibakezelés: minden leágazásnál, HTTP hibakódok explicit visszaadva.
 Frontend: minden bemenet validálva, hálózati és LLM hibákat kulturáltan megjeleníti.
 Health endpoint: /health a monitoringhoz.
 Monitoring: illeszd be Prometheus/Sentry hookokat extra metrikához.

Ezt a kódot éles infrastruktúrában, GCP alatt, saját domainekkel, audit/monitoring pipelinenal tedd production éretté! Ha enterprisegrade továbbfejlesztés vagy részletesebb infra/k8s template kell, jelezd!

Íme a teljes kód, ahogy Repliten production ready módon, titkos kulcsokat a Secrets panelról betöltve, egy FastAPI backenddel és egy letisztult, mobilra is jó frontenddel megvalósíthatsz egy Cerebras Llama 4 Scout + Exa RAG chatbotot.

 1. main.py (FastAPI backend, Replit Secrets támogatással)

python
import os
import requests
from fastapi import FastAPI, HTTPException, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import FileResponse, JSONResponse
from pydantic import BaseModel

# Titkos kulcsok a Replit Secretsből:
EXA_API_KEY = os.getenv("EXA_API_KEY")
CEREBRAS_API_KEY = os.getenv("CEREBRAS_API_KEY")

if not EXA_API_KEY or not CEREBRAS_API_KEY:
    raise RuntimeError("Kérlek, add meg az EXA_API_KEY és CEREBRAS_API_KEY változókat a Secrets panelen!")

app = FastAPI()

# Csak saját vagy trusted originre engedélyezd prod-ban!
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],  # Replit demohoz maradhat *, prod-ban szűkítsd domainre!
    allow_methods=["*"],
    allow_headers=["*"],
    allow_credentials=True,
)

class ChatRequest(BaseModel):
    message: str

@app.post("/chat")
async def chat_endpoint(input: ChatRequest, request: Request):
    user_msg = input.message.strip()
    if not user_msg:
        raise HTTPException(status_code=422, detail="Üres üzenet.")

    # 1. Exa keresés (rövid timeout & hibakezelés)
    try:
        resp = requests.get(
            "https://api.exa.ai/search",
            params={"q": user_msg, "num_results": 8},
            headers={"Authorization": f"Bearer {EXA_API_KEY}"},
            timeout=14
        )
        docs = resp.json().get("results") or resp.json().get("documents") or []
    except Exception as e:
        docs = []

    chunks, sources = [], []
    for d in docs:
        snippet = d.get("snippet") or d.get("text") or ""
        url = d.get("url") or d.get("link") or ""
        if snippet:
            chunks.append(f"{snippet}\nForrás: {url}" if url else snippet)
        if url:
            sources.append(url)
    if not chunks:
        # fallback: minimális context
        chunks = ["(Nem találtam netes forrást, csak az alaptudásból válaszolok.)"]

    web_context = "\n\n".join(chunks[:5])

    llama_prompt = [
        {"role": "system", "content": "Válaszolj tömören, magyarul, a rendelkezésre álló webes források alapján!"},
        {"role": "user", "content": f"{user_msg}\n\nWebes források:\n{web_context}"}
    ]

    payload = {
        "model": "llama-4-scout-17b-16e-instruct",
        "messages": llama_prompt,
        "temperature": 0.7,
        "max_tokens": 512
    }
    try:
        cb_resp = requests.post(
            "https://api.cerebras.ai/v1/chat/completions",
            headers={"Authorization": f"Bearer {CEREBRAS_API_KEY}", "Content-Type": "application/json"},
            json=payload,
            timeout=45
        )
        cb_json = cb_resp.json()
        answer = cb_json["choices"][0]["message"]["content"].strip()
    except Exception as e:
        answer = "⚠️ Hiba történt a válaszgenerálás során, kérlek próbáld újra vagy ellenőrizd a kulcsokat."

    return {
        "answer": answer,
        "sources": sources[:5]
    }

@app.get("/")
def serve_frontend():
    return FileResponse("index.html")

@app.get("/health")
def health():
    return JSONResponse({"status": "ok"})


