    button { padding: 8px 14px; border-radius: 4px; background:#244579; color:#fff; border:none; font-size:1em;}
    button:disabled { background: #a5b9d1;}
    #loading { display:none; color:#597; margin-bottom:9px;}
    @media (max-width: 520px){
      #chatbox{border-radius:0; box-shadow:none;}
      .sources { word-break:break-word; }
    }
  </style>
</head>
<body>
  <div id="chatbox">
    <h2>Llama 4 Scout Webkereső Chatbot</h2>
    <div id="msgs"></div>
    <div id="loading">Válasz betöltése...</div>
    <form id="inputrow" autocomplete="off">
      <input type="text" id="msg" placeholder="Írj ide kérdést..." autocomplete="off"/>
      <button id="sendbtn" type="submit">Küldés</button>
    </form>
  </div>
  <script>
    const msgInput = document.getElementById('msg');
    const msgsDiv = document.getElementById('msgs');
    const loadingDiv = document.getElementById('loading');
    const sendBtn = document.getElementById('sendbtn');

    function addMessage(txt, type, sources=[]) {
      const div = document.createElement("div");
      div.className = "message " + type;
      div.innerHTML = (type === "user" ? "<b>Te:</b> " : "<b>Bot:</b> ") + txt.replace(/\n/g, "<br>");
      if (type === "bot" && sources && sources.length) {
        const srcBlock = document.createElement("div");
        srcBlock.className = "sources";
        srcBlock.innerHTML = "Források:<br>" + sources.map(u => `<a href="${u}" target="_blank" rel="noopener">${u}</a>`).join("<br>");
        div.appendChild(srcBlock);
      }
      msgsDiv.appendChild(div);
      msgsDiv.scrollTop = msgsDiv.scrollHeight;
    }

    async function sendMsg(e){
      e.preventDefault();
      const text = msgInput.value.trim();
      if(!text) return;
      addMessage(text, "user");
      msgInput.value = "";
      msgInput.disabled = true; sendBtn.disabled = true;
      loadingDiv.style.display = "block";
      try{
        const resp = await fetch("/chat", {
          method:"POST",
          headers:{"Content-Type":"application/json"},
          body: JSON.stringify({ message: text })
        });
        const data = await resp.json();
        if(resp.ok && data.answer){
          addMessage(data.answer, "bot", data.sources || []);
        }else{
          addMessage("⚠️ Hiba: " + (data.detail || "ismeretlen hiba"), "bot");
        }
      }catch(e){
        addMessage("⚠️ Hálózati vagy szerver hiba.", "bot");
      }finally{
        loadingDiv.style.display = "none";
        msgInput.disabled = false; sendBtn.disabled = false;
        msgInput.focus();
      }
      return false;
    }
    document.getElementById('inputrow').addEventListener("submit", sendMsg);
    msgInput.focus();
  </script>
</body>
</html>


